function renderAll() {
  renderBalance();
  renderList();
  if (currentView() === 'budgets') renderBudgets();
  if (currentView() === 'reports') renderReport();
}

function init() {
  const now = today();
  $('#date').value = now;
  $('#budget-month').value = now.slice(0, 7);
  $('#report-month').value = now.slice(0, 7);

  $('#add-form').addEventListener('submit', addTransaction);
