}

function drawChart(expenses) {
  const canvas = $('#chart');
  const ctx = canvas.getContext('2d');
  if (!ctx) return;
  const W = canvas.width;
  const H = canvas.height;
  ctx.clearRect(0, 0, W, H);

  const entries = Object.entries(expenses).sort((a, b) => b[1] - a[1]);
